function renderColumnFilter(key,anchor){document.querySelectorAll('.column-menu.open').forEach(x=>x.classList.remove('open'));let menu=anchor.parentElement.querySelector('.column-menu');if(!menu)return;const vals=[...new Set(rows.map(r=>filterValue(colDefs()[key].get(r))))].sort((a,b)=>a==='(tom)'?1:b==='(tom)'?-1:a.localeCompare(b,'no',{numeric:true}));const active=columnFilters.get(key)||new Set();menu.innerHTML=`<div class="cf-actions"><button data-all="1">Alle</button><button data-none="1">Ingen</button></div>`+vals.map(v=>`<label><input type="checkbox" data-val="${esc(v)}" ${!active.size||active.has(v)?'checked':''}> ${esc(v)}</label>`).join('');menu.classList.add('open');menu.querySelector('[data-all]').onclick=e=>{e.stopPropagation();columnFilters.delete(key);renderTable();renderHeaders()};menu.querySelector('[data-none]').onclick=e=>{e.stopPropagation();columnFilters.set(key,new Set(['__NONE__']));menu.querySelectorAll('[data-val]').forEach(x=>x.checked=false);renderTable();renderHeaders()};menu.querySelectorAll('[data-val]').forEach(x=>x.onchange=e=>{e.stopPropagation();let set=columnFilters.get(key);if(!set||!set.size||set.has('__NONE__'))set=new Set();if(x.checked)set.add(x.dataset.val);else set.delete(x.dataset.val);const all=vals.length&&vals.every(v=>set.has(v));if(all||set.size===0)columnFilters.delete(key);else columnFilters.set(key,set);renderTable();renderHeaders()})}
function renderHeaders(){document.querySelectorAll('[data-col]').forEach(th=>{const key=th.dataset.col,sort=th.querySelector('.sort-ind'),filter=th.querySelector('.filter-btn');if(sort)sort.textContent=sortState.key===key?(sortState.dir===1?'▲':sortState.dir===-1?'▼':''):'';if(filter)filter.classList.toggle('active',columnFilters.has(key))})}
function setSort(key){if(sortState.key!==key)sortState={key,dir:1};else if(sortState.dir===1)sortState.dir=-1;else if(sortState.dir===-1)sortState={key:null,dir:0};if(!isProjectProfile()){profiles[activeProfile]=captureProfile();persistProfiles()}renderHeaders();renderTable()}
function resetFilters(){columnFilters.clear();sortState={key:null,dir:0};formatFilters=new Set(allFormats);$('search').value='';renderFormats();renderHeaders();renderTable()}
function visibleRows(){let a=rows.filter(r=>formatFilters.has(r.file.format)&&workspaceScope().has(r.file.id));const q=norm($('search').value);if(q)a=a.filter(r=>[r.file.name,r.file.format,...columnConfig.map(c=>valueForColumn(r,c))].some(v=>norm(v).includes(q)));a=applyColumnFilters(a);return sortRows(a)}
const VALUE_COLORS=[['#DBEAFE','#1E3A8A'],['#DCFCE7','#166534'],['#FEF3C7','#92400E'],['#F3E8FF','#6B21A8'],['#FFE4E6','#9F1239'],['#CFFAFE','#155E75'],['#FFEDD5','#9A3412'],['#E0E7FF','#3730A3'],['#FCE7F3','#9D174D'],['#D1FAE5','#065F46'],['#F1F5F9','#334155'],['#ECFCCB','#3F6212'],['#CCFBF1','#115E59'],['#EDE9FE','#5B21B6'],['#FAE8FF','#86198F'],['#FEE2E2','#991B1B']];
function colorForValue(v){const value=filterValue(v);if(value==='(tom)')return null;let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return VALUE_COLORS[(h>>>0)%VALUE_COLORS.length]}
function renderMetaCell(r,c){const v=valueForColumn(r,c);if(!c.colorize)return `<td>${esc(v)}</td>`;const pair=colorForValue(v);if(!pair)return `<td>${esc(v)}</td>`;return `<td><span class="value-badge" style="background:${pair[0]};color:${pair[1]}">${esc(v)}</span></td>`}
function renderTable(){workspaceModeUI();const a=visibleRows(),n=currentFolder==='__ALL__'?null:findNode(treeRoot,currentFolder);$('currentFolder').textContent=workspaceMode==='explorer'?'Utforsker · valgt innhold':workspaceMode==='validation'?'Egenskapsvalidering':'Dokumentplan';$('visibleCount').textContent=`${a.length} filer`;$('selectAll').checked=a.length>0&&a.every(r=>selected.has(r.file.id));$('selectAll').indeterminate=a.some(r=>selected.has(r.file.id))&&!a.every(r=>selected.has(r.file.id));$('body').innerHTML=a.map(r=>`<tr class="${selected.has(r.file.id)?'selected':''}" data-file="${r.file.id}"><td><input type="checkbox" data-file-check="${r.file.id}" ${selected.has(r.file.id)?'checked':''}></td><td><div class="file-cell"><span>📄</span><b>${esc(r.file.name)}</b></div></td><td><span class="format">${esc((r.file.format||'').toUpperCase())}</span></td><td>${r.file.format==='ifc'?'klar for 3D':'ikke 3D-modell'}</td>${columnConfig.filter(c=>c.visible!==false).map(c=>renderMetaCell(r,c)).join('')}</tr>`).join('')||`<tr><td colspan="20" class="ws-empty">${workspaceScope().size?'Ingen treff med gjeldende filtre.':'Velg mapper eller filer i treet til venstre.'}</td></tr>`;$('body').querySelectorAll('[data-file-check]').forEach(x=>x.onchange=()=>{x.checked?selected.add(x.dataset.fileCheck):selected.delete(x.dataset.fileCheck);updateSelection();renderTree();renderTable()});$('body').querySelectorAll('[data-file]').forEach(tr=>tr.onclick=e=>{if(e.target.matches('input'))return;const id=tr.dataset.file;selected.has(id)?selected.delete(id):selected.add(id);updateSelection();renderTree();renderTable()})}
function renderFormats(){const fs=[...allFormats].sort((a,b)=>a.localeCompare(b,'no'));$('formatMenu').innerHTML=fs.map(f=>`<label class="format-option"><input type="checkbox" data-format="${esc(f)}" ${formatFilters.has(f)?'checked':''}> ${esc(f.toUpperCase())}</label>`).join('');$('formatMenu').querySelectorAll('[data-format]').forEach(x=>x.onchange=()=>{x.checked?formatFilters.add(x.dataset.format):formatFilters.delete(x.dataset.format);$('formatButton').textContent=formatFilters.size===allFormats.size?'Filformater: alle':`Filformater: ${formatFilters.size}/${allFormats.size}`;renderTable()})}
function selectedIds(){return [...selected]}
function selectedRows(){const ids=new Set([...selected].map(String));return rows.filter(r=>ids.has(String(r.file.id)))}
function buildViewerUrl(includeVersions=true, onlyModel=null){const chosen=selectedRows();if(!chosen.length)throw Error('Ingen filer er valgt');let models=chosen.filter(r=>r.file.format==='ifc');if(onlyModel)models=models.filter(r=>String(r.file.id)===String(onlyModel));if(!models.length)throw Error('Ingen valgte IFC-modeller kan åpnes i 3D-vieweren');const projectId=String(project?.id||'').trim();if(!projectId)throw Error('Mangler projectId');const modelIds=models.map(r=>String(r.file.id));const versionIds=models.map(r=>r.file.versionId?String(r.file.versionId):'');const base=`https://web.connect.trimble.com/projects/${encodeURIComponent(projectId)}/viewer/3d/`;const useVersions=includeVersions&&versionIds.length===modelIds.length&&versionIds.every(Boolean);const query=[`projectId=${encodeURIComponent(projectId)}`,`modelId=${modelIds.map(encodeURIComponent).join(',')}`];if(useVersions)query.push(`versionId=${versionIds.map(encodeURIComponent).join(',')}`);const url=`${base}?${query.join('&')}`;log('VIEWER DEEPLINK',{mode:onlyModel?'single':(useVersions?'with-version':'without-version'),projectId,modelCount:modelIds.length,modelIds,versionIdsIncluded:useVersions,versionIds,url});return{url,modelCount:modelIds.length,modelIds}}
