function openSelectedInViewer(includeVersions=true){const {url,modelCount}=buildViewerUrl(includeVersions);openViewerUrl(url);status(`Åpnet ${modelCount} valgte IFC-modeller ${includeVersions?'med':'uten'} versjons-ID`,'ok')}
function testSelectedIndividually(){const {modelIds}=buildViewerUrl(false);for(const id of modelIds){const {url}=buildViewerUrl(false,id);openViewerUrl(url)}status(`Åpnet ${modelIds.length} enkeltmodell-tester uten versjons-ID`,'ok')}
function renderDynamicHeaders(){const tr=document.querySelector('thead tr');if(!tr)return;tr.querySelectorAll('th.dynamic-meta').forEach(x=>x.remove());const marker=[...tr.children].find(x=>x.textContent.trim()==='3D');let after=marker;for(const c of columnConfig.filter(c=>c.visible!==false)){const th=document.createElement('th');th.className='colhead dynamic-meta';th.dataset.col=c.id;th.innerHTML=`<span class="sort-hit">${esc(c.title)} <span class="sort-ind"></span></span><button class="filter-btn" title="Filtrer ${esc(c.title)}">▾</button><div class="column-menu"></div>`;after.insertAdjacentElement('afterend',th);after=th}wireHeaders();renderHeaders()}
