function optionsHtml(selected=''){const grouped={};for(const c of columnConfig)if(c.pset&&c.property){const k=`${c.pset}::${c.property}`;if(!propertyCatalog.has(k))propertyCatalog.set(k,{pset:c.pset,property:c.property})}for(const x of propertyCatalog.values())(grouped[x.pset]??=[]).push(x.property);const groups=Object.keys(grouped);if(!groups.length)return '<option value="" disabled>Ingen IFC-egenskaper funnet ennå</option>';return groups.sort((a,b)=>a.localeCompare(b,'no')).map(ps=>`<optgroup label="${esc(ps)}">${[...new Set(grouped[ps])].sort((a,b)=>a.localeCompare(b,'no')).map(pr=>`<option value="${esc(ps+'::'+pr)}" ${selected===ps+'::'+pr?'selected':''}>${esc(pr)}</option>`).join('')}</optgroup>`).join('')}
function renderSettings(){const body=$('settingsRows');body.innerHTML=columnConfig.map((c,i)=>`<div class="setting-row" data-i="${i}"><input data-title value="${esc(c.title)}"><select data-prop><option value="">Auto/alias</option>${optionsHtml(c.pset&&c.property?c.pset+'::'+c.property:'')}</select><label><input type="checkbox" data-visible ${c.visible!==false?'checked':''}> Vis</label><label><input type="checkbox" data-colorize ${c.colorize?'checked':''}> Fargelegg</label><button data-up>↑</button><button data-down>↓</button><button data-remove>×</button></div>`).join('');body.querySelectorAll('.setting-row').forEach(row=>{const i=+row.dataset.i;row.querySelector('[data-title]').onchange=e=>{columnConfig[i].title=e.target.value||columnConfig[i].title};row.querySelector('[data-prop]').onchange=e=>{if(e.target.value){const [pset,...rest]=e.target.value.split('::');columnConfig[i].pset=pset;columnConfig[i].property=rest.join('::');delete columnConfig[i].aliases}};row.querySelector('[data-visible]').onchange=e=>columnConfig[i].visible=e.target.checked;row.querySelector('[data-colorize]').onchange=e=>columnConfig[i].colorize=e.target.checked;row.querySelector('[data-up]').onclick=()=>{if(i>0)[columnConfig[i-1],columnConfig[i]]=[columnConfig[i],columnConfig[i-1]];renderSettings()};row.querySelector('[data-down]').onclick=()=>{if(i<columnConfig.length-1)[columnConfig[i+1],columnConfig[i]]=[columnConfig[i],columnConfig[i+1]];renderSettings()};row.querySelector('[data-remove]').onclick=()=>{columnConfig.splice(i,1);renderSettings()}})}
function openSettings(){if(isProjectProfile())return status('Lag en personlig kopi for å endre prosjektprofilen','bad');renderSettings();$('settings').classList.add('open')}
function applySettings(){if(isProjectProfile())return status('Lag en personlig kopi for å endre prosjektprofilen','bad');columnFilters.clear();profiles[activeProfile]=captureProfile();persistProfiles();$('settings').classList.remove('open');renderDynamicHeaders();renderTable()}
function addColumn(){columnConfig.push({id:`custom_${Date.now()}`,title:'Ny kolonne',visible:true});renderSettings()}
