function discoveryStats(){const psets={};for(const r of rows){if(r.file.format!=='ifc')continue;for(const [full,value] of Object.entries(r.props||{})){const cut=full.indexOf('::');if(cut<=0)continue;const pset=full.slice(0,cut),property=full.slice(cut+2);const ps=psets[pset]??={models:new Set(),properties:{}};ps.models.add(String(r.file.id));const pr=ps.properties[property]??={models:new Set(),values:new Map()};pr.models.add(String(r.file.id));const v=filterValue(value);pr.values.set(v,(pr.values.get(v)||0)+1)}}return psets}
function renderDiscovery(){const stats=discoveryStats(),names=Object.keys(stats).sort((a,b)=>a.localeCompare(b,'no'));$('discoveryPsets').innerHTML=names.map((n,i)=>`<button class="discovery-pset ${i===0?'active':''}" data-pset="${esc(n)}"><b>${esc(n)}</b><span>${stats[n].models.size} modeller · ${Object.keys(stats[n].properties).length} egenskaper</span></button>`).join('')||'<p>Ingen IFC-egenskaper funnet.</p>';$('discoveryPsets').querySelectorAll('[data-pset]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.discovery-pset').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderDiscoveryProperties(b.dataset.pset,stats)});if(names.length)renderDiscoveryProperties(names[0],stats)}
function renderDiscoveryProperties(pset,stats=discoveryStats()){const props=stats[pset]?.properties||{};$('discoveryTitle').textContent=pset;$('discoveryProps').innerHTML=Object.keys(props).sort((a,b)=>a.localeCompare(b,'no')).map((name,i)=>`<button class="discovery-prop ${i===0?'active':''}" data-prop="${esc(name)}"><b>${esc(name)}</b><span>${props[name].models.size} modeller · ${props[name].values.size} verdier</span></button>`).join('');$('discoveryProps').querySelectorAll('[data-prop]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.discovery-prop').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderDiscoveryValues(pset,b.dataset.prop,props[b.dataset.prop])});if(Object.keys(props).length)renderDiscoveryValues(pset,Object.keys(props).sort((a,b)=>a.localeCompare(b,'no'))[0],props[Object.keys(props).sort((a,b)=>a.localeCompare(b,'no'))[0]])}
function renderDiscoveryValues(pset,property,stat){$('discoveryProperty').textContent=property;$('discoveryValues').innerHTML=[...(stat?.values||new Map()).entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'no',{numeric:true})).map(([v,n])=>`<div class="discovery-value"><span>${esc(v)}</span><b>${n}</b></div>`).join('')||'<p>Ingen verdier.</p>';$('discoveryAdd').onclick=()=>addPropertyColumn(pset,property)}
function addPropertyColumn(pset,property){if(isProjectProfile())return status('Lag en personlig kopi først','bad');const exists=columnConfig.find(c=>c.pset===pset&&c.property===property);if(exists){exists.visible=true}else columnConfig.push({id:`custom_${Date.now()}`,title:property,pset,property,visible:true,colorize:false});profiles[activeProfile]=captureProfile();persistProfiles();renderDynamicHeaders();renderTable();status(`Kolonne lagt til: ${property}`,'ok')}
