function analyticsColumns(){const out=[];for(const c of columnConfig.filter(c=>c.visible!==false))out.push({id:c.id,label:c.title,get:r=>valueForColumn(r,c),colorize:!!c.colorize});return out}
function analyticsData(col){const map=new Map();for(const r of visibleRows()){const v=filterValue(col.get(r));map.set(v,(map.get(v)||0)+1)}return [...map.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'no',{numeric:true}))}
function renderAnalytics(){const cols=analyticsColumns();$('analyticsSelect').innerHTML=cols.map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('');$('analyticsSelect').onchange=renderAnalyticsChart;renderAnalyticsChart()}
function renderAnalyticsChart(){const col=analyticsColumns().find(c=>c.id===$('analyticsSelect').value)||analyticsColumns()[0];if(!col){$('analyticsChart').innerHTML='<p>Ingen synlige metadata-kolonner.</p>';return}const data=analyticsData(col),max=Math.max(1,...data.map(x=>x[1])),total=data.reduce((a,x)=>a+x[1],0);$('analyticsTitle').textContent=`${col.label} · ${total} synlige filer`;$('analyticsChart').innerHTML=data.map(([value,count])=>{const pair=col.colorize?colorForValue(value):null,bg=pair?.[0]||'#1769e0',fg=pair?.[1]||'#fff',pct=Math.max(2,Math.round(count/max*100));return `<div class="analytic-row"><div class="analytic-label" title="${esc(value)}">${esc(value)}</div><div class="analytic-track"><div class="analytic-bar" style="width:${pct}%;background:${bg};color:${fg}"><span>${count}</span></div></div></div>`}).join('')||'<p>Ingen verdier.</p>';$('analyticsCopy').onclick=()=>copyAnalytics(col,data)}
async function copyAnalytics(col,data){const text=[`${col.label};Antall`,...data.map(([v,n])=>`${String(v).replaceAll(';',',')};${n}`)].join('\n');try{await navigator.clipboard.writeText(text);status('Analyse kopiert til utklippstavlen','ok')}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();status('Analyse kopiert til utklippstavlen','ok')}}
function openAnalytics(){renderAnalytics();$('analytics').classList.add('open')}
function validateImportedProfile(raw){if(!raw||typeof raw!=='object')throw Error('Ugyldig profilfil');const src=raw.profile||raw;if(!Array.isArray(src.columns))throw Error('Profilfilen mangler columns');const columns=src.columns.filter(c=>c&&typeof c==='object'&&typeof c.id==='string'&&typeof c.title==='string').map(c=>({id:c.id,title:c.title,aliases:Array.isArray(c.aliases)?c.aliases:undefined,pset:typeof c.pset==='string'?c.pset:undefined,property:typeof c.property==='string'?c.property:undefined,visible:c.visible!==false,colorize:!!c.colorize}));if(!columns.length)throw Error('Profilfilen inneholder ingen gyldige kolonner');const sort=src.sort&&typeof src.sort==='object'?{key:src.sort.key||null,dir:[-1,0,1].includes(src.sort.dir)?src.sort.dir:0}:{key:null,dir:0};return{columns,sort}}
function safeFileName(v){return String(v||'profil').trim().replace(/[^a-zA-Z0-9._-]+/g,'_').replace(/^_+|_+$/g,'')||'profil'}
function exportActiveProfile(){if(!isProjectProfile()){profiles[activeProfile]=captureProfile();persistProfiles()}const payload={schema:'DocLibProfile',schemaVersion:1,exportedFrom:'DocLib v1.35',name:isProjectProfile()?projectProfileMeta[activeProfile]?.name||activeProfile:activeProfile,projectId:String(project?.id||''),profile:cloneData(profiles[activeProfile])};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`DocLib_profile_${safeFileName(activeProfile)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status(`Profil eksportert: ${activeProfile}`,'ok')}
function triggerProfileImport(){$('profileImportFile').value='';$('profileImportFile').click()}
async function importProfileFile(file){if(!file)return;let raw;try{raw=JSON.parse(await file.text())}catch{throw Error('Kunne ikke lese JSON-filen')}if(raw.schema&&raw.schema!=='DocLibProfile')throw Error('Filen er ikke en DocLib-profil');if(raw.schemaVersion&&raw.schemaVersion!==1)throw Error(`Profilformat ${raw.schemaVersion} støttes ikke`);const profile=validateImportedProfile(raw),baseName=String(raw.name||file.name.replace(/\.json$/i,'')||'Importert profil').trim()||'Importert profil';pendingProfileImport={raw,profile,baseName};if(profiles[baseName]){showImportConflict()}else{completeProfileImport(baseName)}}
function showImportConflict(){const p=pendingProfileImport;if(!p)return;$('importConflictName').textContent=p.baseName;$('importConflictSource').textContent=String(p.raw.exportedFrom||'Ikke oppgitt');$('importConflictProject').textContent=String(p.raw.projectId||'Ikke oppgitt');document.querySelector('input[name="importMode"][value="copy"]').checked=true;$('importConflict').classList.add('open')}
function nextCopyName(base){let n=2,name=`${base} (${n})`;while(profiles[name])name=`${base} (${++n})`;return name}
function completeProfileImport(name){const p=pendingProfileImport;if(!p)return;profiles[name]=p.profile;activeProfile=name;applyProfileState(true);persistProfiles();pendingProfileImport=null;$('importConflict').classList.remove('open');status(`Profil importert: ${name}`,'ok')}
function confirmProfileImport(){const p=pendingProfileImport;if(!p)return;const mode=document.querySelector('input[name="importMode"]:checked')?.value||'copy';completeProfileImport(mode==='overwrite'?p.baseName:nextCopyName(p.baseName))}
function cancelProfileImport(){pendingProfileImport=null;$('importConflict').classList.remove('open');status('Profilimport avbrutt')}
function updateSelection(){const count=rows.filter(r=>r.file.format==='ifc'&&selected.has(r.file.id)).length;$('selectionCount').textContent=`${count} IFC-modeller valgt for 3D`}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
// Publisher preview: prepares files locally; never writes to Trimble Connect.
let publisherSession=null,publisherBusy=false;
function publisherCanonical(value){if(Array.isArray(value))return '['+value.map(publisherCanonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+publisherCanonical(value[k])).join(',')+'}';return JSON.stringify(value)}
function publisherValidateConfig(cfg){if(cfg?.schema!=='DocLibProjectConfiguration'||cfg.schemaVersion!==1||!Array.isArray(cfg.profiles))throw Error('Ugyldig prosjektindeks. Ingen filer er endret.');const ids=new Set();for(const e of cfg.profiles){if(!e||typeof e.id!=='string'||!e.id.trim()||ids.has(e.id)||typeof e.name!=='string'||typeof e.file!=='string')throw Error('Prosjektindeksen har ugyldige eller dupliserte profiloppføringer.');publisherSafePath(e.file);ids.add(e.id)}return cfg}
