async function verifyPublisherPackage(){if(publisherBusy||!publisherSession?.prepared)return;publisherBusy=true;$('publisherVerify').disabled=true;try{const s=publisherSession,p=s.prepared;if(String(project.id)!==s.projectId)throw Error('Prosjektet er endret.');const current=await publisherReadContext();if(publisherCanonical(current.config)!==publisherCanonical(p.config))throw Error('Prosjektindeksen samsvarer ikke med pakken. Ingen publisering er bekreftet.');const f=await resolveCfgFile(current.doclib.id,p.path),actual=await readCfgJson(f);if(publisherCanonical(actual)!==publisherCanonical(p.profile))throw Error('Profilfilen samsvarer ikke med pakken.');publisherSetMessage('Bekreftet: både profilfilen og prosjektindeksen samsvarer med pakken. Last DocLib på nytt for å oppdatere prosjektprofilene.')}catch(e){publisherSetMessage(e.message)}finally{publisherBusy=false;$('publisherVerify').disabled=false}}
