// Controlled single-file upload. SDK 4.0.12 TCPS.uploadFileContent wire contract.
// Legacy initiate/commit are deprecated. No fallback, overwrite, index write or retry.
let singleUpload=null,singleBusy=false;
function singleReceiptKey(){return 'doclib-single-upload-v3:'+String(project.id)+':'+String(mineUser?.id||'unresolved')}
function singleMessage(text){$('singleMessage').textContent=text}
function singleReceipt(){try{return JSON.parse(localStorage.getItem(singleReceiptKey())||'null')}catch{return null}}
function singleSaveReceipt(r){localStorage.setItem(singleReceiptKey(),JSON.stringify(r))}
async function singleItems(id){const r=await fetch(`${CORE}/folders/${encodeURIComponent(id)}/items`,{headers:{Authorization:`Bearer ${token}`,Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error(`Kan ikke lese målmappe (HTTP ${r.status}).`);const data=await r.json();if(r.status===206)throw Error('Delvis mappeliste. Opplasting stoppet for å unngå ufullstendig kollisjonskontroll.');return arr(data)}
async function singleBrowse(id,path){if(singleBusy)return;const items=await singleItems(id);singleUpload.folderId=id;singleUpload.path=path;singleUpload.items=items;$('singlePath').textContent=path;$('singleFolders').innerHTML='<option value="">Velg undermappe...</option>'+items.filter(x=>x.type==='FOLDER').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');singleSummary()}
function singleSummary(){identityRender();if(!singleUpload)return;const s=singleUpload;$('singleSummary').textContent=`Prosjekt: ${s.projectName} (${s.projectId})\nKilde: ${s.sourceName}\nMål: ${s.path}/${s.name}\nKolonner: ${s.payload.profile.columns.length}\nIndeks og eksisterende profiler endres ikke.`;$('singleStart').disabled=identityBlocked||singleBusy||s.attempted||!s.folderId||!$('singleConsent').checked}
async function openSingleUpload(){if(singleBusy)return;if(isProjectProfile())return status('Lag en personlig kopi først.','bad');$('singleUpload').classList.add('open');$('singleStart').disabled=true;$('singleConsent').checked=false;singleUpload=null;$('singleConsent').disabled=false;$('singleFolders').disabled=false;$('singleRoot').disabled=false;$('singleConsentText').textContent=' Jeg har valgt en eksisterende testmappe og godtar opplasting av en testfil. Dette er ikke privat profillagring.';singleMessage('Leser prosjekt og mapper. Ingen skrivekall utføres.');try{const profile=publisherValidateProfile(captureProfile()),r=await req(`${CORE}/projects/${encodeURIComponent(project.id)}`);if(!r.ok)throw Error('Kan ikke lese prosjekt.');const rootId=r.data?.rootId||r.data?.rootFolder?.id||r.data?.rootFolderId;if(!rootId)throw Error('Fant ingen rotmappe.');const id='profile-'+crypto.randomUUID();singleUpload={projectId:String(project.id),projectName:r.data.name||String(project.id),rootId,sourceName:activeProfile,name:id+'.json',payload:{schema:'DocLibProfile',schemaVersion:1,id,name:activeProfile,profile:cloneData(profile)},attempted:false};await singleBrowse(rootId,r.data.name||'Prosjekt');const receipt=singleReceipt();$('singleVerify').disabled=!receipt;singleMessage(receipt?`Tidligere forsøk: ${receipt.name} (${receipt.stage}). Kontroller dette før du eventuelt oppretter en ny fil.`:'Velg en eksisterende testmappe. Bekreft sammendraget før opplasting.')}catch(e){singleUpload=null;singleMessage(e.message)}}
async function singlePost(path,body){await identityCheck(path==='/files/fs/commit'?'before_commit':'before_initiate');const r=await fetch(CORE+path,{method:'POST',headers:{Authorization:`Bearer ${token}`,Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body),redirect:'error'});log('SINGLE_UPLOAD HTTP',{path,status:r.status});if(!r.ok)throw Error(`Skriveoperasjon avvist (HTTP ${r.status}). Ingen automatisk gjentakelse.`);return await r.json()}
async function singleVerifyReceipt(){if(singleBusy)return;singleBusy=true;try{await singleVerifyCore()}catch(e){singleMessage(e.message)}finally{singleBusy=false;singleSummary()}}
async function singleVerifyCore(){const r=singleReceipt();if(!r||r.projectId!==String(project.id))throw Error('Ingen kvittering for dette prosjektet.');const matches=(await singleItems(r.folderId)).filter(x=>x.type==='FILE'&&x.name===r.name);if(matches.length!==1)throw Error(`Fant ${matches.length} filer med forventet navn. Ikke bekreftet. Kontroller mappen manuelt; ikke last opp på nytt automatisk.`);const f=matches[0];if(r.fileId&&String(f.id)!==String(r.fileId))throw Error('Fil-ID avviker fra kvitteringen.');const actual=await readCfgJson(f);if(publisherCanonical(actual)!==publisherCanonical(r.payload))throw Error('Innhold avviker. Ikke bekreftet.');r.fileId=f.id;r.stage='verified';singleSaveReceipt(r);singleMessage(`Profilfil lastet opp og kontrollert. Ikke aktivert som prosjektprofil.\nFil: ${r.path}/${r.name}\nFil-ID: ${r.fileId}\nProsjektindeksen er ikke endret.`);log('SINGLE_UPLOAD VERIFIED',{fileId:f.id,name:r.name,folderId:r.folderId})}
async function startSingleUpload(){const s=singleUpload;if(identityBlocked||singleBusy||!s||!s.folderId||s.attempted||!$('singleConsent').checked)return;singleBusy=true;singleSummary();let receipt;try{if(String(project.id)!==s.projectId)throw Error('Prosjektet er endret. Åpne dialogen på nytt.');await identityCheck('upload_preflight');if(s.mine){const resolved=await mineResolve(s.rootId);if(resolved.id!==s.folderId||s.payload.ownerId!==mineUser?.id)throw Error('Brukermål endret. Ingen opplasting.')}const items=await singleItems(s.folderId);if(items.some(x=>String(x.name).toLowerCase()===s.name.toLowerCase()))throw Error('Filnavnet finnes allerede. Ingen opplasting utført.');publisherValidateProfile(s.payload.profile);receipt={projectId:s.projectId,folderId:s.folderId,path:s.path,name:s.name,payload:s.payload,stage:'initiating'};singleSaveReceipt(receipt);s.attempted=true;singleMessage('Starter én opplasting. Ikke lukk eller last siden på nytt.');const init=await singlePost('/files/fs/initiate',{parentId:s.folderId,parentType:'FOLDER',name:s.name});if(!init.uploadId||typeof init.uploadURL!=='string')throw Error('Uventet initiate-respons. Stoppet uten reserveforsøk.');const url=new URL(init.uploadURL);if(url.protocol!=='https:'||url.username||url.password)throw Error('Ugyldig opplastingsadresse.');receipt.stage='put';receipt.uploadId=init.uploadId;singleSaveReceipt(receipt);const body=new Blob([JSON.stringify(s.payload,null,2)],{type:'application/json'});await identityCheck('before_put');const put=await fetch(url.href,{method:'PUT',body,credentials:'omit',redirect:'error'});log('SINGLE_UPLOAD PUT',{status:put.status});if(!put.ok)throw Error(`Filoverføring feilet (HTTP ${put.status}).`);receipt.stage='committing';singleSaveReceipt(receipt);const committed=await singlePost('/files/fs/commit',{uploadId:init.uploadId});receipt.stage='committed';if(committed?.id)receipt.fileId=committed.id;singleSaveReceipt(receipt);$('singleVerify').disabled=false;await singleVerifyCore();if(s.mine){await loadMineProfiles(s.rootId);renderProfileControls()}}catch(e){singleMessage(`${e.message}\n${s.attempted?'Resultatet er ikke bekreftet. Ingen automatisk gjentakelse eller sletting. Bruk Kontroller siste forsøk og kontroller målmappe før nytt forsøk.':'Ingen skrivekall utført.'}`);log('SINGLE_UPLOAD STOP',{stage:receipt?.stage||'preflight',name:s.name});$('singleVerify').disabled=!singleReceipt()}finally{singleBusy=false;singleSummary()}}
function wireSingleUpload(){$('singleOpen').onclick=openSingleUpload;$('singleClose').onclick=()=>{if(!singleBusy)$('singleUpload').classList.remove('open')};$('singleConsent').onchange=singleSummary;$('singleStart').onclick=startSingleUpload;$('singleVerify').onclick=singleVerifyReceipt;$('singleRoot').onclick=()=>{if(singleUpload&&!singleBusy)singleBrowse(singleUpload.rootId,singleUpload.projectName).catch(e=>singleMessage(e.message))};$('singleFolders').onchange=e=>{const f=singleUpload?.items.find(x=>String(x.id)===e.target.value&&x.type==='FOLDER');if(f)singleBrowse(f.id,singleUpload.path+'/'+f.name).catch(e=>singleMessage(e.message))}}


// User folder ACL is configured manually in Connect. This code does not certify privacy.
let mineUser=null,mineFolder=null,mineStatus='Ikke lest';
async function mineIdentify(){try{await identityCheck('startup',true)}catch(_){mineStatus='Identitet utilgjengelig eller endret';$('mineIdentity').textContent='Identitet blokkert'}}
async function mineResolve(rootId){if(!mineUser)throw Error('Ingen bekreftet bruker-ID fra Workspace API.');let id=rootId;for(const name of ['Extension_config','DocLib','users',mineUser.id,'profiles']){const matches=(await singleItems(id)).filter(x=>x.type==='FOLDER'&&x.name===name);if(matches.length!==1)throw Error(`Brukermappe mangler, er utilgjengelig eller er tvetydig: ${name}`);id=matches[0].id}return {id,path:`Extension_config/DocLib/users/${mineUser.id}/profiles`}}
async function loadMineProfiles(rootId){mineLastLoadOk=false;const staged=[],issues=[];mineFolder=null;try{const folder=await mineResolve(rootId);const files=(await singleItems(folder.id)).filter(f=>f.type==='FILE'&&/^profile-[a-z0-9-]+\.json$/i.test(f.name));await pool(files,3,async f=>{try{const raw=await readCfgJson(f);if(raw.schema!=='DocLibProfile'||raw.schemaVersion!==1||raw.ownerId!==mineUser.id||raw.projectId!==String(project.id)||typeof raw.id!=='string'||typeof raw.name!=='string')throw Error('Ugyldig eier eller profil');staged.push({key:'mine:'+f.id,profile:publisherValidateProfile(raw.profile),meta:{name:raw.name,file:f.name,fileId:f.id,profileId:raw.id,ownerId:raw.ownerId,projectId:raw.projectId,scope:'mine',default:false}})}catch(_){issues.push({file:f.name,fileId:f.id,reason:'Kunne ikke lese eller validere profil. Kontroller format, eier og prosjekt.'})}});for(const k of [...projectProfileKeys])if(k.startsWith('mine:')){projectProfileKeys.delete(k);delete profiles[k];delete projectProfileMeta[k]}for(const x of staged){profiles[x.key]=x.profile;projectProfileKeys.add(x.key);projectProfileMeta[x.key]=x.meta}mineFolder=folder;mineIssues=issues;mineLastLoadOk=true;mineStatus=`${staged.length} lastet${issues.length?' · '+issues.length+' ignorert':''}`;mineLoadedAt=new Date().toISOString()}catch(_){for(const k of [...projectProfileKeys])if(k.startsWith('mine:')){projectProfileKeys.delete(k);delete profiles[k];delete projectProfileMeta[k]}mineIssues=[];mineStatus='Innlesing feilet. Ingen lagrede brukerprofiler vises. Kontroller tilgang og brukermappe.'}log('MINE LOAD',{status:mineStatus})}
async function openMineUpload(){if(singleBusy)return;try{await identityCheck('open_mine_upload')}catch(e){return status(e.message,'bad')}if(!mineUser)return status('Bruker-ID utilgjengelig. Ingen opplasting.','bad');if(isProjectProfile())return status('Lag en lokal kopi før du laster opp en ny revisjonsfil.','bad');await openSingleUpload();if(!singleUpload)return;singleUpload.mine=true;singleUpload.folderId=null;$('singleConsent').disabled=true;$('singleStart').disabled=true;try{const folder=await mineResolve(singleUpload.rootId);singleUpload.folderId=folder.id;singleUpload.path=folder.path;singleUpload.payload.ownerId=mineUser.id;singleUpload.payload.projectId=String(project.id);singleUpload.payload.storageScope='user';$('singleConsent').disabled=false;$('singlePath').textContent=folder.path;$('singleFolders').disabled=true;$('singleRoot').disabled=true;$('singleConsent').checked=false;$('singleConsentText').textContent=' Admin har kontrollert at denne mappen kun er tilgjengelig for meg og prosjektadmins. Jeg godtar opplasting. DocLib har ikke verifisert rettighetene.';singleSummary();singleMessage('Mål er låst til innlogget brukers mappe. Ingen rettigheter endres. Admin må kontrollere faktisk tilgang før du krysser av.')}catch(e){singleUpload=null;$('singleStart').disabled=true;singleMessage(e.message+'\nBe admin opprette og sikre brukermappen. Ingen opplasting utført.')}}
function showMineSetup(){alert('Bruker-ID: '+(mineUser?.id||'utilgjengelig')+'\n\nAdmin oppretter:\nExtension_config/DocLib/users/'+(mineUser?.id||'<bruker-ID>')+'/profiles\n\nAdmin må kontrollere arvede rettigheter, gruppetilganger og filtilganger: kun eier og prosjektadmins skal ha tilgang. DocLib endrer eller verifiserer ikke ACL.\n\nGamle lokale profiler er ikke automatisk overtatt av innlogget bruker. Bruk Eksporter i preview.2 og Importer her.')}


// Diagnostics contain only allowlisted identifiers and locally generated metadata.
// No raw API response, email, name, token, signed URL or error message is recorded.
let identityBaseline=null,identityBlocked=false,identityChecks=[],identityPrevious=null,identityChangedAcrossLoads=false;
const identitySource='Workspace API.user.getUser().id';
function identityHistoryKey(){return 'doclib-identity-diagnostics-v1:'+String(project?.id||'unknown')}
function identityValidId(id){return typeof id==='string'&&id.length>0&&id.length<=128&&/^[A-Za-z0-9_-]+$/.test(id)}
function identityFormat(id){return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)?'UUID-format':'annen ID-streng'}
function identityReadPrevious(){try{const x=JSON.parse(localStorage.getItem(identityHistoryKey())||'null');return identityValidId(x?.id)?{id:x.id,observedAt:typeof x.observedAt==='string'?x.observedAt.slice(0,40):null}:null}catch(_){return null}}
function identityReport(){return {version:VERSION,source:identitySource,projectId:String(project?.id||''),baselineId:identityBaseline,blocked:identityBlocked,previousLoad:identityPrevious,changedAcrossLoads:identityChangedAcrossLoads,checks:identityChecks.slice(),note:'ID-format beviser ikke identitet. Ingen aliaser eller mapper endres. Historikk gjelder bare denne nettleseren og dette prosjektet.'}}
function identityRender(){const el=$('identityReport');if(el)el.textContent=JSON.stringify(identityReport(),null,2);const b=$('identityCheck');if(b)b.disabled=singleBusy;const label=$('mineIdentity');if(label){label.textContent=identityBlocked?'Identitet blokkert':(identityBaseline||'Ikke kontrollert');label.title=identitySource}if(identityBlocked){const start=$('singleStart');if(start)start.disabled=true}}
function identityRecord(stage,id,result){const item={observedAt:new Date().toISOString(),stage,source:identitySource,id:id||null,format:id?identityFormat(id):null,result};identityChecks.push(item);if(identityChecks.length>60)identityChecks.shift();log('IDENTITY_DIAGNOSTICS',item);identityRender()}
function identityStop(stage,id,result){identityBlocked=true;identityRecord(stage,id,result);status('Identiteten er endret eller kunne ikke bekreftes. Opplasting er sperret til siden lastes på nytt.','bad')}
async function identityCheck(stage,startup=false){
 let u;try{u=await API.user.getUser()}catch(_){identityStop(stage,null,'getUser_failed');throw Error('Kunne ikke bekrefte identitet. Ingen nye skrivekall tillates i denne økten.')}
 const id=u?.id;if(!identityValidId(id)){identityStop(stage,null,'invalid_id');throw Error('Ugyldig eller manglende bruker-ID. Opplasting er sperret.')}
 if(identityBlocked){identityRecord(stage,id,'blocked_latched');throw Error('Identitetssperren er aktiv. Last siden på nytt etter at innloggingen er kontrollert.')}
 if(identityBaseline===null){if(!startup){identityStop(stage,id,'missing_startup_baseline');throw Error('Oppstartsidentitet mangler. Opplasting er sperret.')}
  identityBaseline=id;mineUser={id};identityPrevious=identityReadPrevious();identityChangedAcrossLoads=!!identityPrevious&&identityPrevious.id!==id;
  try{localStorage.setItem(identityHistoryKey(),JSON.stringify({id,observedAt:new Date().toISOString()}))}catch(_){}
  identityRecord(stage,id,identityChangedAcrossLoads?'different_from_previous_load':'baseline_set');
  if(identityChangedAcrossLoads)log('IDENTITY_PREVIOUS_LOAD_DIFFERENT',{previousId:identityPrevious.id,currentId:id,source:identitySource,note:'Ingen automatisk kobling eller flytting. Kan også skyldes annen innlogget bruker.'});
  return id;
 }
 if(id!==identityBaseline){identityStop(stage,id,'changed_in_session');throw Error('Bruker-ID er endret siden oppstart. Opplasting stoppet. Ingen automatisk ID-kobling eller mappeendring.')}
 identityRecord(stage,id,'matches_baseline');return id;
}
async function identityManualCheck(){if(singleBusy)return;try{await identityCheck('manual')}catch(_){}identityRender()}
function identityOpen(){identityRender();$('identityDialog').classList.add('open')}
async function identityCopy(){const text=JSON.stringify(identityReport(),null,2);try{await navigator.clipboard.writeText(text);$('identityCopyStatus').textContent='Identitetsrapport kopiert.'}catch(_){$('identityCopyStatus').textContent='Kunne ikke kopiere automatisk. Marker og kopier rapporten nedenfor.'}}
function identityWire(){$('identityOpen').onclick=identityOpen;$('identityClose').onclick=()=>$('identityDialog').classList.remove('open');$('identityCheck').onclick=identityManualCheck;$('identityCopy').onclick=identityCopy}


// Explicit recovery of a user-selected local JSON. Never maps owner identities.
let recoveryPending=null,recoveryBusy=false,recoverySequence=0;
function recoveryMessage(t){$('recoveryMessage').textContent=t}
function recoveryReset(){recoveryPending=null;$('recoveryApply').disabled=true;$('recoverySummary').textContent='';$('recoveryConsent').checked=false}
function recoveryUniqueName(base){let n=base,i=2;while(Object.prototype.hasOwnProperty.call(profiles,n)||n in Object.prototype)n=base+' ('+(i++)+')';return n}
function recoverySafeName(value){const n=String(value||'').trim();if(!n||n.length>120||/[\x00-\x1f]/.test(n)||['__proto__','constructor','prototype'].includes(n)||n.startsWith('mine:')||n.startsWith('project:'))throw Error('Velg et vanlig profilnavn på 1–120 tegn, uten reserverte prefikser.');return n}
function recoveryUpdate(){const p=recoveryPending;$('recoveryApply').disabled=recoveryBusy||!p||identityBlocked||!$('recoveryConsent').checked;}
function recoveryOpen(){if(recoveryBusy||singleBusy)return;recoverySequence++;recoveryReset();$('recoveryFile').value='';$('recoveryName').value='';recoveryMessage('Velg en JSON-profil du har lastet ned fra prosjektet. Ingen prosjektfiler endres.');$('recoveryDialog').classList.add('open')}
async function recoveryRead(file){if(recoveryBusy)return;const seq=++recoverySequence;recoveryReset();if(!file)return;try{if(file.size>2*1024*1024)throw Error('Profilfilen er større enn 2 MB.');const raw=JSON.parse(await file.text());if(seq!==recoverySequence)return;if(!raw||raw.schema!=='DocLibProfile'||raw.schemaVersion!==1||!raw.profile)throw Error('Forventet DocLibProfile med schemaVersion 1 og profile.');const clean=publisherValidateProfile(raw.profile);const id=await identityCheck('recovery_review');if(seq!==recoverySequence)return;const sourceOwner=typeof raw.ownerId==='string'?raw.ownerId.slice(0,128):null;const sourceProject=typeof raw.projectId==='string'?raw.projectId.slice(0,128):null;const base=typeof raw.name==='string'?raw.name.slice(0,90):'Gjenopprettet profil';recoveryPending={profile:cloneData(clean),reviewUser:id,reviewProject:String(project.id)};$('recoveryName').value=recoveryUniqueName((base.trim()||'Gjenopprettet profil')+' · lokal kopi');$('recoverySummary').textContent=`Fil: ${file.name}\nKildeeier (kun informasjon): ${sourceOwner||'ikke angitt'}\nKildeprosjekt (kun informasjon): ${sourceProject||'ikke angitt'}\nInnlogget ID: ${id}\nKolonner: ${clean.columns.length}\n${sourceOwner&&sourceOwner!==id?'Eier-ID avviker. Dette bekrefter ikke at ID-ene tilhører samme person.\n':''}${sourceProject&&sourceProject!==String(project.id)?'Kildeprosjekt avviker fra aktivt prosjekt.\n':''}Kun kolonneoppsett og gyldig sortering kopieres. Ingen eier-ID, profil-ID eller prosjekt-ID overtas.`;recoveryMessage('Kontroller oppsett og nytt navn. Dette oppretter bare en lokal kopi, ikke en opplasting.');recoveryUpdate()}catch(e){if(seq!==recoverySequence)return;recoveryReset();recoveryMessage(e.message)}}
async function recoveryApply(){const p=recoveryPending;if(recoveryBusy||!p||identityBlocked||!$('recoveryConsent').checked)return;recoveryBusy=true;recoveryUpdate();try{const name=recoverySafeName($('recoveryName').value);if(Object.prototype.hasOwnProperty.call(profiles,name)||name in Object.prototype)throw Error('Navnet finnes allerede. Velg et nytt navn; ingen profil overskrives.');const id=await identityCheck('recovery_apply');if(id!==p.reviewUser||String(project.id)!==p.reviewProject)throw Error('Bruker eller prosjekt er endret. Les filen på nytt.');const profile=publisherValidateProfile(p.profile);const locals={};for(const [k,v] of Object.entries(profiles))if(!projectProfileKeys.has(k))Object.defineProperty(locals,k,{value:v,enumerable:true,writable:true,configurable:true});Object.defineProperty(locals,name,{value:cloneData(profile),enumerable:true,writable:true,configurable:true});localStorage.setItem(profileKey(),JSON.stringify({active:name,profiles:locals}));Object.defineProperty(profiles,name,{value:cloneData(profile),enumerable:true,writable:true,configurable:true});activeProfile=name;recoveryPending=null;applyProfileState(true);recoveryMessage('Lokal kopi opprettet: '+name+'. Kilde og prosjektfiler er urørt. Bruk Lagre i Mine profiler som en separat handling når brukermappens rettigheter er kontrollert.');$('recoveryConsent').checked=false;log('PROFILE_RECOVERY_LOCAL_COPY',{columns:profile.columns.length,networkWrites:0})}catch(e){recoveryMessage(e.message)}finally{recoveryBusy=false;recoveryUpdate()}}
function recoveryWire(){$('recoveryOpen').onclick=recoveryOpen;$('recoveryClose').onclick=()=>{if(!recoveryBusy){recoverySequence++;recoveryReset();$('recoveryDialog').classList.remove('open')}};$('recoveryFile').onchange=e=>recoveryRead(e.target.files?.[0]);$('recoveryConsent').onchange=recoveryUpdate;$('recoveryApply').onclick=recoveryApply}


// Read-only server profile manager. Editing creates a separate local copy.
let mineManagerBusy=false,mineLastLoadOk=false,mineLoadedAt=null,mineIssues=[];
function mineManagerKeys(){return [...projectProfileKeys].filter(k=>k.startsWith('mine:')&&profiles[k]).sort((a,b)=>(projectProfileMeta[a]?.name||a).localeCompare(projectProfileMeta[b]?.name||b,'nb')||a.localeCompare(b))}
function mineManagerRender(){const sel=$('mineManagerList'),old=sel.value,keys=mineManagerKeys();sel.innerHTML=keys.map(k=>{const m=projectProfileMeta[k];return `<option value="${esc(k)}">${esc(m.name)} · ${esc(m.fileId||k)}</option>`}).join('');if(keys.includes(old))sel.value=old;else if(keys.includes(activeProfile))sel.value=activeProfile;$('mineManagerStatus').textContent=`${mineStatus}\nSist vellykket innlesing: ${mineLoadedAt||'ikke registrert'}\nInnlogget ID: ${mineUser?.id||'utilgjengelig'}\nMappe: ${mineFolder?.path||'ikke tilgjengelig'}\nRettigheter er ikke automatisk verifisert.`;$('mineManagerIssues').textContent=mineIssues.length?mineIssues.map(x=>`${x.file}: ${x.reason}`).join('\n'):'Ingen ignorerte profilfiler registrert ved siste fullførte innlesing.';mineManagerDetails()}
function mineManagerDetails(){const k=$('mineManagerList').value,m=projectProfileMeta[k],p=profiles[k];$('mineManagerDetails').textContent=m&&p?JSON.stringify({name:m.name,file:m.file,fileId:m.fileId,profileId:m.profileId,ownerId:m.ownerId,projectId:m.projectId,columns:p.columns.length,sort:p.sort},null,2):'Velg en lagret profil.';for(const id of ['mineManagerUse','mineManagerCopy'])$(id).disabled=mineManagerBusy||identityBlocked||!m||!p;$('mineManagerRefresh').disabled=mineManagerBusy||singleBusy}
function mineManagerOpen(){if(singleBusy||recoveryBusy)return;mineManagerRender();$('mineManager').classList.add('open')}
async function mineManagerRefresh(){if(mineManagerBusy||singleBusy)return;mineManagerBusy=true;mineManagerDetails();try{await identityCheck('mine_manager_refresh');const r=await req(`${CORE}/projects/${encodeURIComponent(project.id)}`);if(!r.ok)throw Error('Kunne ikke lese prosjekt.');const rootId=r.data?.rootId||r.data?.rootFolder?.id||r.data?.rootFolderId;if(!rootId)throw Error('Fant ingen rotmappe.');await loadMineProfiles(rootId);applyProfileState(true);$('mineManagerMessage').textContent=mineLastLoadOk?'Mine profiler er lest på nytt. Ingen modellmetadata er lastet på nytt.':'Innlesing feilet. Tidligere brukerprofiler er fjernet fra visningen; ingen serverfiler er endret.'}catch(_){$('mineManagerMessage').textContent='Oppdatering stoppet. Kontroller identitetsdiagnostikk, tilgang og prosjekt. Ingen serverfiler er endret.'}finally{mineManagerBusy=false;mineManagerRender()}}
async function mineManagerUse(){if(mineManagerBusy||singleBusy)return;const k=$('mineManagerList').value;if(!k?.startsWith('mine:')||!profiles[k])return;mineManagerBusy=true;mineManagerDetails();try{await identityCheck('mine_manager_use');if(!profiles[k])throw Error('Profilen finnes ikke lenger.');activeProfile=k;applyProfileState(true);$('mineManagerMessage').textContent='Lagret profil er valgt. Den er skrivebeskyttet; opprett lokal kopi for redigering.'}catch(_){$('mineManagerMessage').textContent='Kunne ikke velge profil. Kontroller identiteten og oppdater listen.'}finally{mineManagerBusy=false;mineManagerDetails()}}
async function mineManagerCopy(){if(mineManagerBusy||singleBusy||recoveryBusy)return;const k=$('mineManagerList').value;if(!k?.startsWith('mine:')||!profiles[k])return;mineManagerBusy=true;mineManagerDetails();try{await identityCheck('mine_manager_copy');const p=publisherValidateProfile(profiles[k]);const base=String(projectProfileMeta[k]?.name||'Min profil').slice(0,85)+' · lokal kopi';const name=recoverySafeName(recoveryUniqueName(base));const local={};for(const [n,v] of Object.entries(profiles))if(!projectProfileKeys.has(n))Object.defineProperty(local,n,{value:v,enumerable:true});Object.defineProperty(local,name,{value:cloneData(p),enumerable:true});localStorage.setItem(profileKey(),JSON.stringify({active:name,profiles:local}));Object.defineProperty(profiles,name,{value:cloneData(p),enumerable:true,writable:true,configurable:true});activeProfile=name;applyProfileState(true);$('mineManagerMessage').textContent=`Lokal kopi opprettet: ${name}. Rediger oppsettet og bruk Lagre i Mine profiler som en separat handling. Dette lager fortsatt en ny fil, ikke en oppdatering av kilden.`}catch(_){$('mineManagerMessage').textContent='Lokal kopi kunne ikke opprettes. Kontroller identitet og lokal lagringsplass.'}finally{mineManagerBusy=false;mineManagerDetails()}}
function mineManagerWire(){$('mineManagerOpen').onclick=mineManagerOpen;$('mineManagerClose').onclick=()=>{if(!mineManagerBusy)$('mineManager').classList.remove('open')};$('mineManagerList').onchange=mineManagerDetails;$('mineManagerRefresh').onclick=mineManagerRefresh;$('mineManagerUse').onclick=mineManagerUse;$('mineManagerCopy').onclick=mineManagerCopy}


// UI only: move existing controls, retain their original handlers and IDs.
function uiCloseMenus(except=null){document.querySelectorAll('.ui-menu[open]').forEach(d=>{if(d!==except)d.open=false})}
function uiPositionMenu(d){const panel=d.querySelector('.ui-menu-panel'),r=d.querySelector('summary').getBoundingClientRect();const width=Math.min(290,Math.max(0,window.innerWidth-16));panel.style.width=width+'px';panel.style.left=Math.max(8,Math.min(r.left,window.innerWidth-width-8))+'px';const below=window.innerHeight-r.bottom-16,above=r.top-16;const down=below>=Math.min(260,above);panel.style.maxHeight=Math.max(40,down?below:above)+'px';panel.style.top=down?(r.bottom+6)+'px':'auto';panel.style.bottom=down?'auto':(window.innerHeight-r.top+6)+'px'}
function uiCleanupWire(){const menus=[...document.querySelectorAll('.ui-menu')];for(const d of menus){d.addEventListener('toggle',()=>{if(d.open){uiCloseMenus(d);uiPositionMenu(d)}});d.querySelector('.ui-menu-panel').addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.disabled){d.open=false;queueMicrotask(()=>{if(document.activeElement===b)d.querySelector('summary').focus()})}})}document.addEventListener('click',e=>{if(!e.target.closest('.ui-menu'))uiCloseMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=menus.find(x=>x.open);if(d){e.preventDefault();d.open=false;d.querySelector('summary').focus()}}});document.addEventListener('focusin',e=>{for(const d of menus)if(d.open&&!d.contains(e.target))d.open=false});window.addEventListener('resize',()=>uiCloseMenus());window.addEventListener('scroll',e=>{if(!e.target.closest?.('.ui-menu-panel'))uiCloseMenus()},true)}


// Read-only project publishing preflight. Never authorizes an index write.
let publisherPreflightBusy=false,publisherPreflightReport=null;
function publisherCurrentOptions(){return {mode:$('publisherMode').value,target:$('publisherTarget').value,name:$('publisherName').value,description:$('publisherDescription').value,makeDefault:$('publisherDefault').checked}}
function publisherPreflightInvalidate(){publisherPreflightReport=null;$('publisherPreflightReport').textContent='Forhåndskontroll er ikke kjørt for gjeldende valg.'}
function publisherPreflightAssess(session,current,opts,uid){if(String(project.id)!==session.projectId)throw Error('Prosjektet er endret. Åpne dialogen på nytt.');if(publisherCanonical(current.config)!==session.baseline)throw Error('Prosjektindeksen er endret siden dialogen ble åpnet. Åpne dialogen på nytt.');if(current.doclib?.id!==session.context.doclib?.id||current.configFile?.id!==session.context.configFile?.id)throw Error('Konfigurasjonsfil eller målmappe er endret. Åpne dialogen på nytt.');const pack=publisherBuildPackage(session,opts,uid);return {version:VERSION,checkedAt:new Date().toISOString(),projectId:session.projectId,sourceProfile:session.sourceName,action:opts.mode==='update'?'Oppdater eksisterende':'Ny prosjektprofil',targetProfile:pack.profile.name,targetId:pack.id,targetPath:current.folder+'/DocLib/'+pack.path,columns:pack.profile.profile.columns.length,indexPresent:!!current.configFile,indexUnchangedAtRead:true,previousDefault:current.config.defaultProfile||null,proposedDefault:pack.config.defaultProfile||null,changesDefault:(current.config.defaultProfile||null)!==(pack.config.defaultProfile||null),localPackageValidation:'Bestått',automaticPublishing:'SPERRET: betinget innholdsoppdatering og konflikthåndtering er ikke verifisert',permissions:'Ikke kontrollert. Ingen prøveopplasting utført.',concurrency:'Ekstra lesing er ikke atomisk beskyttelse. Manuell publisering kan kollidere.',provisionalId:opts.mode!=='update',note:'Ingen filer er skrevet. Ny profil-ID er foreløpig; ZIP-generering oppretter egen ID.'}}
async function runPublisherPreflight(){if(publisherPreflightBusy||publisherBusy||!publisherSession)return;publisherPreflightBusy=true;$('publisherPreflight').disabled=true;$('publisherPrepare').disabled=true;publisherPreflightReport=null;$('publisherPreflightReport').textContent='Leser prosjektindeksen på nytt. Ingen skrivekall.';const session=publisherSession,opts=publisherCurrentOptions();try{await identityCheck('project_publish_preflight');const current=await publisherReadContext();if(publisherSession!==session||publisherCanonical(opts)!==publisherCanonical(publisherCurrentOptions()))throw Error('Valgene er endret under kontrollen. Kjør kontrollen på nytt.');const report=publisherPreflightAssess(session,current,opts,crypto.randomUUID());publisherPreflightReport=report;$('publisherPreflightReport').textContent=JSON.stringify(report,null,2);log('PUBLISHER PREFLIGHT',{projectId:report.projectId,localPackageValidation:report.localPackageValidation,automaticPublishingEnabled:false})}catch(e){$('publisherPreflightReport').textContent='Forhåndskontroll stoppet: '+e.message+'\nIngen filer er skrevet.'}finally{publisherPreflightBusy=false;$('publisherPreflight').disabled=false;$('publisherPrepare').disabled=!publisherSession}}
