// Assisted project publishing. Shared index is NEVER written by this client.
let assistedBusy=false,assistedPlan=null;
function assistedKey(){return 'doclib-assisted-publication-v1:'+String(project.id)+':'+String(mineUser?.id||'unresolved')}
function assistedSave(r){localStorage.setItem(assistedKey(),JSON.stringify(r))}
function assistedReceipt(){const r=JSON.parse(localStorage.getItem(assistedKey())||'null');if(!r)return null;if(r.projectId!==String(project.id)||r.userId!==mineUser?.id)throw Error('Kvitteringen tilhører annen bruker eller prosjekt.');publisherValidateConfig(r.pack.config);publisherValidateProfile(r.pack.profile.profile);publisherSafePath(r.pack.path);return r}
function assistedMessage(t){$('assistedMessage').textContent=t}
async function assistedGet(path){const r=await fetch(CORE+path,{headers:{Authorization:`Bearer ${token}`,Accept:'application/json'},cache:'no-store',redirect:'error'});if(!r.ok)throw Error('Lesekall feilet (HTTP '+r.status+').');return r.json()}
