async function valRun(){if(valBusy)return;const files=treeRoot?flatten(treeRoot).filter(f=>workspaceScopes.validation.has(f.id)&&f.format==='ifc'):[];if(!files.length)return;valBusy=true;valAbort=new AbortController();valReport={version:VERSION,projectId:project.id,startedAt:new Date().toISOString(),signature:valSelectionSignature(),rules:[],files:[],complete:false};valMessage='Leser regler...';workspaceModeUI();try{const rules=await valLoadRules(valAbort.signal);valReport.rules=rules;for(const file of files){if(valAbort.signal.aborted)throw new DOMException('Avbrutt','AbortError');if(project.id!==valReport.projectId)throw Error('Prosjekt endret.');valMessage='Kontrollerer '+file.name;valRender();valReport.files.push(await valFile(file,rules,valAbort.signal));valRender()}valReport.complete=!valAbort.signal.aborted&&valReport.files.length===files.length&&valReport.files.every(f=>f.status!=='Kunne ikke kontrolleres');valMessage=valReport.complete?'Kjøring avsluttet. Godkjent gjelder kun innleste regler og oppgitt filversjon.':'Kjøring ufullstendig. Se feilstatus per fil.'}catch(e){valMessage=e.name==='AbortError'?'Avbrutt. Ingen fullstendig kontroll.':e.message;valReport.error=valMessage}finally{valBusy=false;valReport.finishedAt=new Date().toISOString();workspaceModeUI()}}
function valExport(){if(!valReport||valBusy)return;const data={...valReport,currentSelectionMatches:valReport.signature===valSelectionSignature()};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='DocLib_validation_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function valRender(){if(workspaceMode!=='validation')return;const selectedFiles=treeRoot?flatten(treeRoot).filter(f=>workspaceScopes.validation.has(f.id)):[],ifc=selectedFiles.filter(f=>f.format==='ifc'),stale=valReport&&valReport.signature!==valSelectionSignature(),files=valReport?.files||[],counts={};for(const f of files)counts[f.status]=(counts[f.status]||0)+1;const shown=files.filter(f=>valFilter==='all'||f.status===valFilter);$('workspacePlaceholder').innerHTML=`<h2>Egenskapsvalidering</h2><p>${ifc.length} IFC-filer valgt · ${selectedFiles.length-ifc.length} andre filer utelates. Regler: Extension_config/properties</p><div class="val-actions"><button id="valRun" class="btn primary" ${valBusy||!ifc.length?'disabled':''}>Kjør validering</button><button id="valCancel" class="btn" ${!valBusy?'disabled':''}>Avbryt</button><button id="valExport" class="btn" ${valBusy||!valReport?'disabled':''}>Eksporter rapport · JSON</button><select id="valFilter" aria-label="Resultatfilter">${['all','Godkjent','Avvik','Advarsler','Ikke relevant','Kunne ikke kontrolleres'].map(x=>`<option value="${esc(x)}" ${x===valFilter?'selected':''}>${x==='all'?'Alle resultater':x}</option>`).join('')}</select></div><p role="status">${esc(valMessage)}</p>${stale?'<p class="val-alert">Utvalg eller filversjon er endret siden kjøringen. Resultatene nedenfor gjelder forrige utvalg.</p>':''}<p>Godkjent gjelder kun relevante objekter og reglene som faktisk traff. Null regeltreff er ikke en bestått kontroll.</p><p>${esc(Object.entries(counts).map(([k,v])=>k+': '+v).join(' · '))}</p>${valReport?.rules.length?`<details><summary>Regelsett brukt (${valReport.rules.length})</summary><ul>${valReport.rules.map(x=>`<li>${esc(x.file)} · ${esc(x.rule.pset)} · ${esc(x.rule.scope.mode)}${x.rule.scope.pset?' ('+esc(x.rule.scope.pset)+')':''}</li>`).join('')}</ul></details>`:''}${shown.map(f=>`<details class="val-result"><summary><strong>${esc(f.name)}</strong> · ${esc(f.status)} · ${f.objects} objekter · ${f.findings.length} avvik/advarsler</summary><p>Versjon: ${esc(f.versionId)}. Kontrollerte objekt/regel-kombinasjoner: ${f.checks}.</p>${f.error?`<p class="val-alert">${esc(f.error)}. Eventuelle avvik nedenfor er bare delresultater.</p>`:''}<p>Regeltreff: ${esc(JSON.stringify(f.ruleMatches))}</p>${f.findings.length?`<div class="val-table"><table><thead><tr><th>Objekt-ID</th><th>Pset / egenskap</th><th>Faktisk</th><th>Forventet</th><th>Avvik</th></tr></thead><tbody>${f.findings.slice(0,500).map(x=>`<tr><td>${esc(x.objectId)}</td><td>${esc(x.pset)} / ${esc(x.property)}</td><td>${esc(JSON.stringify(x.actual))}</td><td>${esc(x.expected)}</td><td>${esc(x.severity)}: ${esc(x.message)}</td></tr>`).join('')}</tbody></table></div>${f.findings.length>500?'<p>Viser første 500 avvik. Eksport inneholder alle registrerte avvik.</p>':''}`:'<p>Ingen registrerte avvik. Se status og regeltreff før resultatet tolkes.</p>'}</details>`).join('')}`;$('valRun').onclick=valRun;$('valCancel').onclick=()=>valAbort?.abort();$('valExport').onclick=valExport;$('valFilter').onchange=e=>{valFilter=e.target.value;valRender()}}

window.addEventListener('load',init);
